mapper.select:
SELECT EXISTS(
  SELECT 1 FROM workspace_invite
  WHERE token_hash = #{tokenHash}
    AND status = 'pending' AND expires_at > UTC_TIMESTAMP()
)

mapper.update:
UPDATE workspace_invite
SET status = 'accepted', accepted_by_id = #{userId}, accepted_at = UTC_TIMESTAMP()
WHERE id = #{id}
  AND token_hash = #{tokenHash}
  AND workspace_id = #{workspaceId}
  AND status = 'pending'
  AND expires_at > UTC_TIMESTAMP()

UPDATE workspace_invite
SET status = 'accepted', accepted_by_id = #{userId}, accepted_at = UTC_TIMESTAMP()
WHERE id = #{id}
  AND token_hash = #{tokenHash}
  AND exchanged_at IS NOT NULL
  AND workspace_id = #{workspaceId}
  AND status = 'pending'
  AND expires_at > UTC_TIMESTAMP()
